mapper.select:
SELECT ANY_VALUE ( mr.team_id ) AS team_id, ANY_VALUE ( mr.member_id ) AS member_id, MAX( mr.start_time ) AS start_time, MAX( mr.end_time ) AS end_time, ANY_VALUE ( mr.create_time ) AS create_time, ANY_VALUE ( m.member_name ) AS member_name, GROUP_CONCAT( r.role_name ) AS role_name FROM team_link l LEFT JOIN team_member_rel mr ON l.team_id = mr.team_id LEFT JOIN org_member m ON m.id = mr.member_id LEFT JOIN team_member_role_rel mrr ON mrr.team_id = mr.team_id AND mrr.member_id = mr.member_id LEFT JOIN sys_role r ON r.id = mrr.role_id
INNER JOIN ( SELECT DISTINCT t.team_id, CASE WHEN t.user_id = #{pageDTO.userId} THEN t.create_user_id ELSE t.user_id END AS user_id FROM team_member_rel t WHERE (t.user_id = #{pageDTO.userId} OR t.create_user_id = #{pageDTO.userId})
AND t.team_id = #{pageDTO.teamId}
AND EXISTS ( SELECT 1 FROM team_link tl WHERE tl.team_id = t.team_id AND tl.module_id = #{pageDTO.moduleId} AND tl.data_id = #{pageDTO.dataId} )
) u ON (mr.user_id = u.user_id OR mr.user_id = #{pageDTO.userId}) AND mr.team_id = u.team_id
WHERE l.data_id = #{pageDTO.dataId} AND mr.team_id IS NOT null
AND EXISTS ( SELECT 1 FROM team_link tl WHERE tl.team_id = l.team_id AND tl.module_id = #{pageDTO.moduleId} )
AND l.team_id = #{pageDTO.teamId}
GROUP BY mr.member_id
